"use client";
import { useInfiniteQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import axios from "axios";

const fetchNotifications = async ({ pageParam = 1 }) => {
  const res = await axios.get(`/api/contact?page=${pageParam}&limit=10`);
  return res.data;
};

export function useNotifications() {
  const queryClient = useQueryClient();

  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = useInfiniteQuery({
    queryKey: ["notifications"],
    queryFn: fetchNotifications,
    initialPageParam: 1,
    getNextPageParam: (lastPage) => lastPage.nextPage ?? undefined,
  });

  const notifications = data?.pages.flatMap((page) => page.contacts) ?? [];

  const markAsRead = useMutation({
    mutationFn: async ({ id, isRead }: { id: string; isRead: boolean }) =>
      axios.patch(`/api/contact/${id}`, { isRead }),
    onMutate: async ({ id, isRead }) => {
      // Optimistic update
      await queryClient.cancelQueries({ queryKey: ["notifications"] });
      const prevData = queryClient.getQueryData(["notifications"]);

      queryClient.setQueryData(["notifications"], (old: any) => {
        if (!old) return old;
        return {
          ...old,
          pages: old.pages.map((page: any) => ({
            ...page,
            contacts: page.contacts.map((n: any) =>
              n.id === id ? { ...n, isRead } : n
            ),
          })),
        };
      });

      return { prevData };
    },
    onError: (_err, _variables, context) => {
      if (context?.prevData)
        queryClient.setQueryData(["notifications"], context.prevData);
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["notifications"] });
    },
  });

  const handleMarkAsRead = (id: string) => markAsRead.mutate({ id, isRead: true });

  return {
    notifications,
    handleMarkAsRead,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  };
}
